  /// `POST /chinese-astrology/bazi/chart`
  Future<GenerateBaziChartResponse> generateBaziChart({
    required String date,
    required String time,
    required NumOrString timezone,
    num? latitude,
    num? longitude,
    DayBoundary? dayBoundary,
    YearBoundary? yearBoundary,
    HourClock? hourClock,
    Lang? lang,
  }) async => model(GenerateBaziChartResponse.fromJson)(
    await _transport.send(
      'POST',
      '/chinese-astrology/bazi/chart',
      query: <String, Object?>{'lang': ?lang?.wire},
